  1→//go:build e2e
  2→
  3→package agents
  4→
  5→import (
  6→	"context"
  7→	"encoding/json"
  8→	"errors"
  9→	"fmt"
 10→	"os"
 11→	"os/exec"
 12→	"strings"
 13→	"time"
 14→)
 15→
 16→func init() {
 17→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "kiro" {
 18→		return
 19→	}
 20→	if _, err := exec.LookPath("kiro-cli"); err != nil {
 21→		return
 22→	}
 23→	Register(&Kiro{})
 24→	// Kiro uses Amazon Q API which may have rate limits
 25→	RegisterGate("kiro", 1)
 26→}
 27→
 28→// Kiro implements the Agent interface for Amazon's Kiro CLI.
 29→type Kiro struct{}
 30→
 31→func (k *Kiro) Name() string               { return "kiro" }
 32→func (k *Kiro) Binary() string             { return "kiro-cli" }
 33→func (k *Kiro) EntireAgent() string        { return "kiro" }
 34→func (k *Kiro) PromptPattern() string      { return `!>` }
 35→func (k *Kiro) TimeoutMultiplier() float64 { return 1.5 }
 36→
 37→func (k *Kiro) IsTransientError(out Output, _ error) bool {
 38→	combined := out.Stdout + out.Stderr
 39→	for _, p := range []string{"overloaded", "rate limit", "503", "529", "throttl"} {
 40→		if strings.Contains(strings.ToLower(combined), p) {
 41→			return true
 42→		}
 43→	}
 44→	return false
 45→}
 46→
 47→func (k *Kiro) Bootstrap() error {
 48→	// kiro-cli uses Amazon Q / Builder ID auth.
 49→	// On CI, ensure auth is available; locally, auth is handled by the desktop app.
 50→	if os.Getenv("CI") == "" {
 51→		return nil
 52→	}
 53→
 54→	if isTruthyEnvValue(os.Getenv("AMAZON_Q_SIGV4")) {
 55→		if err := validateKiroSIGV4Inputs(
 56→			os.Getenv("AWS_REGION"),
 57→			os.Getenv("AWS_ACCESS_KEY_ID"),
 58→			os.Getenv("AWS_SECRET_ACCESS_KEY"),
 59→		); err != nil {
 60→			return fmt.Errorf("kiro-cli sigv4 auth check failed: %w", err)
 61→		}
 62→		return nil
 63→	}
 64→
 65→	// Verify login status — fail fast if not authenticated.
 66→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
 67→	defer cancel()
 68→	cmd := exec.CommandContext(ctx, "kiro-cli", "whoami", "-f", "json")
 69→	out, err := cmd.CombinedOutput()
 70→	if err != nil {
 71→		return fmt.Errorf(
 72→			"kiro-cli auth check failed (run `kiro-cli login --use-device-flow`): %s",
 73→			strings.TrimSpace(string(out)),
 74→		)
 75→	}
 76→	if err := validateKiroWhoamiJSON(out); err != nil {
 77→		return fmt.Errorf("kiro-cli auth check failed: %w", err)
 78→	}
 79→	return nil
 80→}
 81→
 82→func isTruthyEnvValue(v string) bool {
 83→	value := strings.TrimSpace(v)
 84→	if value == "" {
 85→		return false
 86→	}
 87→	lower := strings.ToLower(value)
 88→	return lower != "0" && lower != "false"
 89→}
 90→
 91→func validateKiroSIGV4Inputs(region, accessKeyID, secretAccessKey string) error {
 92→	if strings.TrimSpace(region) == "" {
 93→		return errors.New("AWS_REGION is required when AMAZON_Q_SIGV4 is enabled")
 94→	}
 95→	if strings.TrimSpace(accessKeyID) == "" {
 96→		return errors.New("AWS_ACCESS_KEY_ID is required when AMAZON_Q_SIGV4 is enabled")
 97→	}
 98→	if strings.TrimSpace(secretAccessKey) == "" {
 99→		return errors.New("AWS_SECRET_ACCESS_KEY is required when AMAZON_Q_SIGV4 is enabled")
100→	}
101→	return nil
102→}
103→
104→func validateKiroWhoamiJSON(out []byte) error {
105→	var response struct {
106→		Account json.RawMessage `json:"account"`
107→	}
108→
109→	if err := json.Unmarshal(out, &response); err != nil {
110→		return fmt.Errorf("invalid whoami JSON: %w", err)
111→	}
112→	if len(response.Account) == 0 {
113→		return errors.New("account is missing")
114→	}
115→	if strings.EqualFold(strings.TrimSpace(string(response.Account)), "null") {
116→		return errors.New("account is null")
117→	}
118→	return nil
119→}
120→
121→func (k *Kiro) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
122→	cfg := &runConfig{}
123→	for _, o := range opts {
124→		o(cfg)
125→	}
126→
127→	// kiro-cli --no-interactive mode does not fire agent hooks, so we must
128→	// use interactive (tmux) mode and send the prompt through the TUI.
129→	timeout := 2 * time.Minute
130→	if cfg.PromptTimeout > 0 {
131→		timeout = cfg.PromptTimeout
132→	}
133→
134→	// --agent entire activates the agent profile that contains our hooks
135→	args := []string{"chat", "-a", "--agent", "entire"}
136→	if cfg.Model != "" {
137→		args = append(args, "--model", cfg.Model)
138→	}
139→
140→	name := fmt.Sprintf("kiro-run-%d", time.Now().UnixNano())
141→	s, err := NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, k.Binary(), args...)
142→	if err != nil {
143→		return Output{}, fmt.Errorf("starting kiro session: %w", err)
144→	}
145→	defer func() { _ = s.Close() }()
146→
147→	// Wait for initial prompt — kiro-cli TUI shows "!>" in trust-all mode
148→	if _, err := s.WaitFor(k.PromptPattern(), 30*time.Second); err != nil {
149→		content := s.Capture()
150→		return Output{
151→			Command: k.Binary() + " " + strings.Join(args, " "),
152→			Stderr:  content,
153→		}, fmt.Errorf("waiting for kiro startup: %w", err)
154→	}
155→	s.stableAtSend = ""
156→
157→	// Send the prompt
158→	if err := s.Send(prompt); err != nil {
159→		return Output{}, fmt.Errorf("sending prompt to kiro: %w", err)
160→	}
161→
162→	// Wait for "Credits:" which only appears after the agent finishes a response.
163→	// More reliable than PromptPattern for single-prompt mode since it uniquely
164→	// identifies response completion without needing to distinguish echoed input.
165→	content, err := s.WaitFor(`Credits:`, timeout)
166→	exitCode := 0
167→	if err != nil {
168→		exitCode = -1
169→	}
170→
171→	return Output{
172→		Command:  k.Binary() + " " + strings.Join(args, " ") + " " + fmt.Sprintf("%q", prompt),
173→		Stdout:   content,
174→		ExitCode: exitCode,
175→	}, err
176→}
177→
178→func (k *Kiro) StartSession(ctx context.Context, dir string) (Session, error) {
179→	name := fmt.Sprintf("kiro-test-%d", time.Now().UnixNano())
180→	s, err := NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, k.Binary(), "chat", "-a", "--agent", "entire")
181→	if err != nil {
182→		return nil, err
183→	}
184→
185→	// Wait for the prompt indicator — kiro-cli TUI shows "!>" in trust-all mode
186→	if _, err := s.WaitFor(k.PromptPattern(), 15*time.Second); err != nil {
187→		_ = s.Close()
188→		return nil, fmt.Errorf("waiting for kiro startup prompt: %w", err)
189→	}
190→	s.stableAtSend = ""
191→
192→	return &KiroSession{TmuxSession: s}, nil
193→}
194→
195→// KiroSession wraps TmuxSession for Kiro's interactive sessions.
196→// After Send, WaitFor uses an end-of-line pattern to avoid matching
197→// the echoed "!>" prompt in the input line.
198→type KiroSession struct {
199→	*TmuxSession
200→}
201→
202→func (s *KiroSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
203→	// For initial waits (before any Send), use the original pattern ("!>").
204→	if s.stableAtSend == "" {
205→		return s.TmuxSession.WaitFor(pattern, timeout)
206→	}
207→	// After a Send, the echoed input line contains "!>" with text after it
208→	// (e.g., "[entire] 3% !> now commit it"). The real prompt has "!>" at
209→	// end-of-line (e.g., "[entire] 3% !>"). Match only the latter.
210→	return s.TmuxSession.WaitFor(`(?m)!>\s*$`, timeout)
211→}
