 49→// ParseHookEvent translates a Kiro hook into a normalized lifecycle Event.
 50→// Returns nil for hooks with no lifecycle significance (preToolUse, postToolUse).
 51→func (k *KiroAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 52→	switch hookName {
 53→	case HookNameAgentSpawn:
 54→		return k.parseAgentSpawn(ctx, stdin)
 55→	case HookNameUserPromptSubmit:
 56→		return k.parseUserPromptSubmit(ctx, stdin)
 57→	case HookNameStop:
 58→		return k.parseStop(ctx, stdin)
 59→	case HookNamePreToolUse, HookNamePostToolUse:
 60→		// Pass-through hooks with no lifecycle significance
 61→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 62→	default:
 63→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 64→	}
