 67→// readHookInputOrEmpty wraps ReadAndParseHookInput, returning a zero-value
 68→// hookInputRaw on empty stdin instead of erroring. This supports the Kiro IDE
 69→// which delivers data via environment variables rather than JSON on stdin.
 70→// Malformed JSON still returns an error.
 71→func readHookInputOrEmpty(stdin io.Reader) (*hookInputRaw, error) {
 72→	raw, err := agent.ReadAndParseHookInput[hookInputRaw](stdin)
 73→	if err != nil {
 74→		if errors.Is(err, agent.ErrEmptyHookInput) {
 75→			return &hookInputRaw{}, nil
 76→		}
 77→		return nil, err
 78→	}
 79→	return raw, nil
 80→}
