 82→func (k *KiroAgent) parseAgentSpawn(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
 83→	_, err := readHookInputOrEmpty(stdin)
 84→	if err != nil {
 85→		return nil, err
 86→	}
 87→
 88→	// Generate a new stable session ID and cache it for subsequent hooks.
 89→	// Kiro's SQLite transcript isn't populated until the turn ends, so we can't
 90→	// use the native conversation_id as our session ID — it would be "unknown"
 91→	// at agentSpawn/userPromptSubmit and change to the real ID at stop.
 92→	sessionID := k.generateAndCacheSessionID(ctx)
 93→
 94→	return &agent.Event{
 95→		Type:      agent.SessionStart,
 96→		SessionID: sessionID,
 97→		Timestamp: time.Now(),
 98→	}, nil
 99→}
