101→func (k *KiroAgent) parseUserPromptSubmit(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
102→	raw, err := readHookInputOrEmpty(stdin)
103→	if err != nil {
104→		return nil, err
105→	}
106→
107→	// IDE mode: prompt comes from USER_PROMPT env var when stdin is empty.
108→	prompt := raw.Prompt
109→	if prompt == "" {
110→		prompt = os.Getenv("USER_PROMPT")
111→	}
112→
113→	// Read the stable session ID generated at agentSpawn.
114→	sessionID := k.readCachedSessionID(ctx)
115→	if sessionID == "" {
116→		// Fallback: generate new ID if cache file is missing (e.g., agentSpawn was skipped).
117→		sessionID = k.generateAndCacheSessionID(ctx)
118→	}
119→
120→	return &agent.Event{
121→		Type:      agent.TurnStart,
122→		SessionID: sessionID,
123→		Prompt:    prompt,
124→		Timestamp: time.Now(),
125→	}, nil
126→}
