128→func (k *KiroAgent) parseStop(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
129→	raw, err := readHookInputOrEmpty(stdin)
130→	if err != nil {
131→		return nil, err
132→	}
133→
134→	// IDE mode: CWD may not be in stdin. Fall back to repo root.
135→	cwd := raw.CWD
136→	if cwd == "" {
137→		repoRoot, rootErr := paths.WorktreeRoot(ctx)
138→		if rootErr == nil {
139→			cwd = repoRoot
140→		}
141→	}
142→
143→	// Read the stable session ID generated at agentSpawn.
144→	sessionID := k.readCachedSessionID(ctx)
145→	if sessionID == "" {
146→		// Fallback: try SQLite for the session ID.
147→		sid, queryErr := k.querySessionID(ctx, cwd)
148→		if queryErr != nil || sid == "" {
149→			sessionID = "unknown"
150→		} else {
151→			sessionID = sid
152→		}
153→	}
154→
155→	// At stop, Kiro's SQLite transcript is available. Fetch and cache it
156→	// under our stable session ID so lifecycle.go can read it.
157→	var sessionRef string
158→	sessionRef, err = k.ensureCachedTranscript(ctx, cwd, sessionID)
159→	if err != nil {
160→		logging.Debug(ctx, "kiro: ensureCachedTranscript failed (best-effort)", slog.String("error", err.Error()))
161→	}
162→
163→	// IDE mode: SQLite may not exist. Try the IDE's workspace session files.
164→	if sessionRef == "" {
165→		sessionRef, err = k.ensureIDETranscript(ctx, cwd, sessionID)
166→		if err != nil {
167→			logging.Debug(ctx, "kiro: ensureIDETranscript failed (best-effort)", slog.String("error", err.Error()))
168→		}
169→	}
170→
171→	// Last resort: create a minimal placeholder so the lifecycle handler can
172→	// proceed (file-diff checkpoints still work without a real transcript).
173→	if sessionRef == "" {
174→		sessionRef = k.createPlaceholderTranscript(ctx, cwd, sessionID)
175→	}
176→
177→	// Clear the cache so a subsequent session doesn't reuse this stale ID
178→	// (e.g., if Kiro resumes without firing agentSpawn).
179→	k.clearCachedSessionID(ctx)
180→
181→	return &agent.Event{
182→		Type:       agent.TurnEnd,
183→		SessionID:  sessionID,
184→		SessionRef: sessionRef,
185→		Timestamp:  time.Now(),
186→	}, nil
187→}
