189→// createPlaceholderTranscript writes a minimal JSON transcript to .entire/tmp/
190→// so the lifecycle handler can proceed when the real transcript is unavailable
191→// (e.g., Kiro IDE mode where SQLite is at a different path).
192→func (k *KiroAgent) createPlaceholderTranscript(ctx context.Context, cwd, sessionID string) string {
193→	repoRoot, err := paths.WorktreeRoot(ctx)
194→	if err != nil {
195→		repoRoot = cwd
196→	}
197→	if repoRoot == "" {
198→		return ""
199→	}
200→	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
201→	cachePath := filepath.Join(cacheDir, sessionID+".json")
202→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
203→		logging.Warn(ctx, "kiro: failed to create transcript cache dir", "err", err)
204→		return ""
205→	}
206→	if err := os.WriteFile(cachePath, []byte("{}"), 0o600); err != nil {
207→		logging.Warn(ctx, "kiro: failed to write placeholder transcript", "err", err)
208→		return ""
209→	}
210→	return cachePath
211→}
