213→// generateAndCacheSessionID creates a new random session ID and writes it
214→// to .entire/tmp/kiro-active-session for subsequent hooks to read.
215→func (k *KiroAgent) generateAndCacheSessionID(ctx context.Context) string {
216→	sid := generateSessionID()
217→	cachePath := k.sessionIDCachePath(ctx)
218→	if err := os.MkdirAll(filepath.Dir(cachePath), 0o750); err != nil {
219→		logging.Warn(ctx, "kiro: failed to create session ID cache dir", "err", err)
220→		return sid
221→	}
222→	if err := os.WriteFile(cachePath, []byte(sid), 0o600); err != nil {
223→		logging.Warn(ctx, "kiro: failed to write session ID cache", "err", err)
224→	}
225→	return sid
226→}
