228→// clearCachedSessionID removes the session ID cache file so that a subsequent
229→// session does not accidentally reuse a stale ID from a previous session.
230→func (k *KiroAgent) clearCachedSessionID(ctx context.Context) {
231→	cachePath := k.sessionIDCachePath(ctx)
232→	if err := os.Remove(cachePath); err != nil && !os.IsNotExist(err) {
233→		logging.Warn(ctx, "kiro: failed to clear session ID cache", "err", err)
234→	}
235→}
