237→// readCachedSessionID reads the stable session ID from .entire/tmp/kiro-active-session.
238→// Returns empty string if the cache file doesn't exist.
239→func (k *KiroAgent) readCachedSessionID(ctx context.Context) string {
240→	cachePath := k.sessionIDCachePath(ctx)
241→	data, err := os.ReadFile(cachePath) //nolint:gosec // cachePath is constructed from WorktreeRoot + constant suffix
242→	if err != nil {
243→		return ""
244→	}
245→	return strings.TrimSpace(string(data))
246→}
