248→// sessionIDCachePath returns the path to the session ID cache file.
249→func (k *KiroAgent) sessionIDCachePath(ctx context.Context) string {
250→	repoRoot, err := paths.WorktreeRoot(ctx)
251→	if err != nil {
252→		repoRoot = "."
253→	}
254→	return filepath.Join(repoRoot, ".entire", "tmp", sessionIDFile)
