257→// generateSessionID creates a random 32-character hex string for use as a session ID.
258→func generateSessionID() string {
259→	b := make([]byte, 16)
260→	if _, err := rand.Read(b); err != nil {
261→		// crypto/rand.Read never fails on supported platforms, but use timestamp fallback.
262→		return "kiro-" + time.Now().Format("20060102-150405")
263→	}
264→	return hex.EncodeToString(b)
265→}
