351→		return false
352→	}
353→
354→	var rawSettings map[string]json.RawMessage
355→	if err := json.Unmarshal(data, &rawSettings); err != nil {
356→		return false
357→	}
358→
359→	raw, ok := rawSettings[trustedCommandsKey]
360→	if !ok {
361→		return false
362→	}
363→
364→	var commands []string
365→	if err := json.Unmarshal(raw, &commands); err != nil {
366→		return false
367→	}
368→
369→	want := trustedCommand(localDev)
