378→// installTrustedCommands adds the Entire trusted command pattern to .vscode/settings.json.
379→func installTrustedCommands(worktreeRoot string, localDev bool) error {
380→	settingsPath := filepath.Join(worktreeRoot, vscodeSettingsDir, vscodeSettingsFile)
381→
382→	var rawSettings map[string]json.RawMessage
383→
384→	existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path constructed from repo root
385→	if readErr == nil {
386→		if err := json.Unmarshal(existingData, &rawSettings); err != nil {
387→			return fmt.Errorf("failed to parse %s: %w", vscodeSettingsFile, err)
388→		}
389→	} else {
390→		rawSettings = make(map[string]json.RawMessage)
391→	}
392→
393→	var commands []string
394→	if raw, ok := rawSettings[trustedCommandsKey]; ok {
395→		if err := json.Unmarshal(raw, &commands); err != nil {
396→			return fmt.Errorf("failed to parse %s: %w", trustedCommandsKey, err)
397→		}
398→	}
399→
400→	want := trustedCommand(localDev)
401→	for _, c := range commands {
402→		if c == want {
403→			return nil // already present
404→		}
405→	}
406→
407→	commands = append(commands, want)
408→	raw, err := json.Marshal(commands)
409→	if err != nil {
410→		return fmt.Errorf("failed to marshal %s: %w", trustedCommandsKey, err)
411→	}
412→	rawSettings[trustedCommandsKey] = raw
413→
414→	if err := os.MkdirAll(filepath.Join(worktreeRoot, vscodeSettingsDir), 0o750); err != nil {
415→		return fmt.Errorf("failed to create %s directory: %w", vscodeSettingsDir, err)
416→	}
417→
418→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
419→	if err != nil {
420→		return fmt.Errorf("failed to marshal %s: %w", vscodeSettingsFile, err)
421→	}
422→
423→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
424→		return fmt.Errorf("failed to write %s: %w", vscodeSettingsFile, err)
425→	}
426→
427→	return nil
428→}
429→
430→// uninstallTrustedCommands removes Entire trusted command patterns from .vscode/settings.json.
431→func uninstallTrustedCommands(worktreeRoot string) error {
432→	settingsPath := filepath.Join(worktreeRoot, vscodeSettingsDir, vscodeSettingsFile)
433→
434→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path constructed from repo root
435→	if err != nil {
436→		if os.IsNotExist(err) {
437→			return nil
438→		}
439→		return fmt.Errorf("failed to read %s: %w", vscodeSettingsFile, err)
440→	}
441→
442→	var rawSettings map[string]json.RawMessage
443→	if err := json.Unmarshal(data, &rawSettings); err != nil {
444→		return fmt.Errorf("failed to parse %s: %w", vscodeSettingsFile, err)
445→	}
446→
447→	raw, ok := rawSettings[trustedCommandsKey]
448→	if !ok {
449→		return nil
450→	}
451→
452→	var commands []string
453→	if err := json.Unmarshal(raw, &commands); err != nil {
454→		return fmt.Errorf("failed to parse %s: %w", trustedCommandsKey, err)
455→	}
456→
457→	filtered := make([]string, 0, len(commands))
458→	for _, c := range commands {
459→		if !isEntireTrustedCommand(c) {
460→			filtered = append(filtered, c)
461→		}
462→	}
463→
464→	if len(filtered) == 0 {
465→		delete(rawSettings, trustedCommandsKey)
466→	} else {
467→		raw, err := json.Marshal(filtered)
468→		if err != nil {
469→			return fmt.Errorf("failed to marshal %s: %w", trustedCommandsKey, err)
470→		}
471→		rawSettings[trustedCommandsKey] = raw
472→	}
473→
474→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
475→	if err != nil {
476→		return fmt.Errorf("failed to marshal %s: %w", vscodeSettingsFile, err)
477→	}
478→
479→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
480→		return fmt.Errorf("failed to write %s: %w", vscodeSettingsFile, err)
481→	}
482→
483→	return nil
484→}
